-- TUY CHON: an cac truyen mau cu; KHONG xoa sach/chuong/tai khoan.
-- Sao luu database truoc khi chay. Cac sach da sua ten/tac gia/gioi thieu hoac co bia duoc giu nguyen.
USE [SachMoiDaDen];
GO
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;
